BFS.example:
from collections import deque
def bfs(graph, start):
    q, seen, dist = deque([start]), {start}, {start: 0}
    while q:
        u = q.popleft()
        for v in graph[u]:
            if v not in seen:
                seen.add(v); dist[v] = dist[u] + 1; q.append(v)
    return dist

divide and conquer.example:
def mergesort(a):
    if len(a) <= 1: return a
    m = len(a)//2
    L, R = mergesort(a[:m]), mergesort(a[m:])
    return merge(L, R)

